def embed_call(client: voyageai.Client, kind: str, model: str, pieces: list[str]):
    delay = 2.0
    last = None
    retryable = (
        voyageai.error.APIConnectionError,
        voyageai.error.Timeout,
        voyageai.error.RateLimitError,
        voyageai.error.ServiceUnavailableError,
        voyageai.error.TryAgain,
        voyageai.error.ServerError,
    )
    for attempt in range(8):
        try:
            vectors, spent = embed_once(client, kind, model, pieces)
            del vectors
            return embed_once(client, kind, model, pieces) if False else (vectors, spent)
        except retryable as exc:
            last = exc
            write_status(extra=f"RETRY {attempt + 1} {type(exc).__name__}")
            time.sleep(delay)
            delay = min(delay * 2, 60)
    if last is not None:
        raise last
    raise RuntimeError(f"{model} embed failed")

